#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_pattern;
uniform float amzp_colorMode;
uniform float amzp_levels;
uniform float amzp_pixelSize;
uniform float amzp_spread;
uniform float amzp_contrast;
uniform float amzp_gamma;
uniform float amzp_invert;
layout(color) uniform half4 amzp_colorLow;
layout(color) uniform half4 amzp_colorMid;
layout(color) uniform half4 amzp_colorHigh;
uniform float amzp_alpha;
uniform float amzp_blendMode;
    float4 newLayer(float4 a, float4 b) { return a * (1. - b.a) + b; }
    float bayer2(float2 v) { v = floor(v); return fract(v.y * v.y * .75 + v.x * .5); }
    float bayer4(float2 v) { return bayer2(.5 * v) * .25 + bayer2(v); }
    float bayer8(float2 v) { return bayer4(.5 * v) * .25 + bayer2(v); }
    float bayer16(float2 v) { return bayer8(.5 * v) * .25 + bayer2(v); }
    float hash(float2 p) { return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453); }
    float threshold(float2 cell, int pat) {
        if (pat == 0) return bayer2(cell);
        if (pat == 1) return bayer4(cell);
        if (pat == 2) return bayer8(cell);
        if (pat == 3) return bayer16(cell);
        if (pat == 4) return hash(cell);
        if (pat == 5) {
            float2 f = fract(cell / 4.0) - 0.5;
            return clamp(1.0 - length(f) * 2.2, 0.0, 1.0);
        }
        float2 g = fract(cell / 3.0);
        return g.y;
    }
    float lum(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    void amzRender() {
        float4 texColor = amzTexture(0, amzScreenNorm());
        float3 base = texColor.a > 0.0001 ? texColor.rgb / texColor.a : float3(0.0);
        float lv = max(2.0, floor(amzp_levels + 0.5));
        float ps = max(1.0, floor(amzp_pixelSize + 0.5));
        float2 cell = floor(float4(amzCoord.x/1.0,(screen.w-amzCoord.y)/1.0,0.0,1.0).xy / ps);
        float d = (threshold(cell, int(amzp_pattern)) - 0.5) * amzp_spread;
        float3 col = clamp((base - 0.5) * amzp_contrast + 0.5, 0.0, 1.0);
        col = pow(col, float3(1.0 / max(0.1, amzp_gamma)));
        float3 outRgb;
        if (int(amzp_colorMode) == 0 || int(amzp_colorMode) == 1) {
            float g = lum(col);
            float q = floor(g * (lv - 1.0) + d + 0.5) / (lv - 1.0);
            q = clamp(q, 0.0, 1.0);
            outRgb = (int(amzp_colorMode) == 0) ? float3(step(0.5, q)) : float3(q);
        } else if (int(amzp_colorMode) == 2) {
            float3 q = floor(col * (lv - 1.0) + d + 0.5) / (lv - 1.0);
            outRgb = clamp(q, 0.0, 1.0);
        } else {
            float g = lum(col);
            if (int(amzp_colorMode) == 3) {
                float q = clamp(floor(g * (lv - 1.0) + d + 0.5) / (lv - 1.0), 0.0, 1.0);
                outRgb = mix(amzp_colorLow.rgb, amzp_colorHigh.rgb, q);
            } else {
                float q = clamp(floor(g * (lv - 1.0) + d + 0.5) / (lv - 1.0), 0.0, 1.0);
                outRgb = q < 0.5 ? mix(amzp_colorLow.rgb, amzp_colorMid.rgb, q * 2.0)
                                 : mix(amzp_colorMid.rgb, amzp_colorHigh.rgb, (q - 0.5) * 2.0);
            }
        }
        if ((amzp_invert>0.5)) outRgb = 1.0 - outRgb;
        float4 factor = float4(outRgb, 1.0);
        float4 resultfinal;
        if (int(amzp_blendMode) == 0) {
            resultfinal = factor * texColor.a;
        } else if (int(amzp_blendMode) == 1) {
            float3 c = factor.rgb + (1.0 - factor.a);
            resultfinal = float4(base * c, 1.0) * texColor.a;
        } else if (int(amzp_blendMode) == 2) {
            resultfinal = float4(1.0 - (1.0 - base) * (1.0 - factor.rgb), 1.0) * texColor.a;
        } else {
            resultfinal = newLayer(float4(base, 1.0), factor) * texColor.a;
        }
        amzOutput = mix(texColor, resultfinal, amzp_alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
